    <script>
        /* ===========================================
           SLIDE PRESENTATION CONTROLLER
           =========================================== */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.progressBar = document.getElementById('progressBar');
                this.currentSlideIndex = 0;

                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.updateProgressBar();
            }

            setupIntersectionObserver() {
                const observerOptions = {
                    root: null,
                    rootMargin: '0px',
                    threshold: 0.5 // Trigger when 50% of slide is visible
                };

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');

                            // Update current index based on visible slide
                            this.slides.forEach((slide, index) => {
                                if (slide === entry.target) {
                                    this.currentSlideIndex = index;
                                    this.updateProgressBar();
                                }
                            });
                        }
                    });
                }, observerOptions);

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown' || e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlideIndex + 1);
                    } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlideIndex - 1);
                    }
                });
            }

            goToSlide(index) {
                if (index >= 0 && index < this.slides.length) {
                    this.slides[index].scrollIntoView({ behavior: 'smooth' });
                }
            }

            updateProgressBar() {
                if (this.progressBar && this.slides.length > 1) {
                    const progress = (this.currentSlideIndex / (this.slides.length - 1)) * 100;
                    this.progressBar.style.width = `${progress}%`;
                }
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
